import { z } from 'zod';
import {
  BUDGET_CATEGORIES,
  PROJECT_SOURCES,
  PROJECT_STATUSES,
  PROJECT_TYPES,
  type BudgetCategory,
  type ClientType,
  type ProjectSource,
  type ProjectStatus,
  type ProjectType,
} from '../enums';
import { nonNegativeMoneySchema } from '../money';
import {
  dateOnlySchema,
  enumField,
  isOnOrAfter,
  optionalDate,
  optionalInt,
  optionalMoney,
  optionalPercent,
  optionalText,
  optionalUuid,
  requiredText,
} from './common';
import { paginationQuerySchema } from './pagination';

/** Project code: PRJ-YYYY-NNN (generated by the API). */
export const PROJECT_CODE_REGEX = /^PRJ-\d{4}-\d{3,}$/;

const projectFields = z.object({
  name: requiredText(200),
  type: enumField(PROJECT_TYPES),
  source: enumField(PROJECT_SOURCES),
  clientId: z.uuid('REQUIRED'),
  location: optionalText(200),
  description: optionalText(2000),
  contractValue: optionalMoney,
  contractNo: optionalText(100),
  tenderNo: optionalText(100),
  startDate: dateOnlySchema,
  plannedEndDate: dateOnlySchema,
  revisedEndDate: optionalDate,
  actualEndDate: optionalDate,
  status: enumField(PROJECT_STATUSES).optional(),
  /** Defaults to the `billing` settings when left empty on create. */
  retentionPct: optionalPercent,
  retentionCapPct: optionalPercent,
  advanceAmount: optionalMoney,
  advanceRecoveryPct: optionalPercent,
  dlpMonths: optionalInt(0, 120),
  /** Manual physical progress % (used when there is no BOQ). */
  progressPct: optionalPercent,
  siteSupervisorWorkerId: optionalUuid,
  notes: optionalText(2000),
});

type DateFields = {
  startDate?: string | null;
  plannedEndDate?: string | null;
  revisedEndDate?: string | null;
  actualEndDate?: string | null;
};

/** End dates must not be before the start date. Shared by create, update and the API merge check. */
export function projectDateIssues(v: DateFields): { path: keyof DateFields; message: string }[] {
  const issues: { path: keyof DateFields; message: string }[] = [];
  for (const key of ['plannedEndDate', 'revisedEndDate', 'actualEndDate'] as const) {
    if (!isOnOrAfter(v.startDate, v[key])) issues.push({ path: key, message: 'END_BEFORE_START' });
  }
  return issues;
}

const refineDates = (v: DateFields, ctx: z.RefinementCtx) => {
  for (const issue of projectDateIssues(v)) {
    ctx.addIssue({ code: 'custom', path: [issue.path], message: issue.message });
  }
};

export const projectCreateSchema = projectFields.superRefine(refineDates);
export type ProjectCreateInput = z.input<typeof projectCreateSchema>;
export type ProjectCreate = z.output<typeof projectCreateSchema>;
export const projectUpdateSchema = projectFields.partial().superRefine(refineDates);
export type ProjectUpdate = z.output<typeof projectUpdateSchema>;

export const projectListQuerySchema = paginationQuerySchema.extend({
  status: z.enum(PROJECT_STATUSES).optional(),
  type: z.enum(PROJECT_TYPES).optional(),
  source: z.enum(PROJECT_SOURCES).optional(),
  clientId: z.uuid().optional(),
});
export type ProjectListQuery = z.infer<typeof projectListQuerySchema>;

export const budgetLineSchema = z.object({
  category: enumField(BUDGET_CATEGORIES),
  amount: nonNegativeMoneySchema,
  notes: optionalText(500),
});
/** PUT /projects/:id/budget — the full set of lines; categories left out are removed. */
export const budgetUpdateSchema = z.object({
  lines: z
    .array(budgetLineSchema)
    .max(BUDGET_CATEGORIES.length)
    .refine((lines) => new Set(lines.map((l) => l.category)).size === lines.length, {
      message: 'DUPLICATE_CATEGORY',
    }),
});
export type BudgetUpdateInput = z.input<typeof budgetUpdateSchema>;
export type BudgetUpdate = z.output<typeof budgetUpdateSchema>;

export interface BudgetLineDto {
  id: string;
  category: BudgetCategory;
  amount: string;
  notes: string | null;
}

export interface ProjectDto {
  id: string;
  code: string;
  name: string;
  type: ProjectType;
  source: ProjectSource;
  clientId: string;
  location: string | null;
  description: string | null;
  contractValue: string;
  contractNo: string | null;
  tenderNo: string | null;
  startDate: string;
  plannedEndDate: string;
  revisedEndDate: string | null;
  actualEndDate: string | null;
  status: ProjectStatus;
  retentionPct: string;
  retentionCapPct: string;
  advanceAmount: string;
  advanceRecoveryPct: string;
  dlpMonths: number;
  progressPct: string | null;
  siteSupervisorWorkerId: string | null;
  notes: string | null;
  createdAt: string;
  updatedAt: string;
  client: { id: string; name: string; type: ClientType };
  totalBudget: string;
}

export interface ProjectDetailDto extends ProjectDto {
  budgetLines: BudgetLineDto[];
  siteSupervisor: { id: string; code: string; fullName: string } | null;
}

export interface BudgetDto {
  lines: BudgetLineDto[];
  total: string;
}
